package com.finance.tracker.business.domain

import kotlin.io.encoding.Base64
import kotlin.test.*

class CashXlsxCellValueTest {
    // Synthetic workbooks isolate native error codes, value presence and string-index decoding.
    private val files = mapOf(
        "absent" to "",
        "empty" to "",
        "number" to "",
        "known" to "",
        "numeric-missing" to "",
        "numeric-empty" to "",
        "numeric-date-empty" to "",
        "shared-missing" to "",
        "shared-empty" to "",
        "shared-space" to "",
        "shared-invalid" to "",
        "boolean-missing" to "",
        "plain-string-space" to ""
    )
    @Test fun missingErrorValueAndKnownCodeKeepTheirNativeText() {
        for ((kind, text) in listOf("absent" to "#NULL!", "known" to "#NUM!")) {
            val document = readLocalCashXlsxDocument(Base64.decode(files.getValue(kind)), "wechat")
            assertEquals(1, document.rows.size)
            assertEquals(text, document.rows.single().payload?.get("金额(元)"))
        }
    }
    @Test fun nonErrorCellsKeepValuePresenceAndPlainStringWhitespace() {
        for ((kind, text) in listOf("numeric-missing" to "", "numeric-empty" to "0", "numeric-date-empty" to "1899-12-31 00:00", "shared-missing" to "", "shared-empty" to "", "shared-space" to "", "shared-invalid" to "", "boolean-missing" to "FALSE", "plain-string-space" to " \t\n ")) {
            val document = readLocalCashXlsxDocument(Base64.decode(files.getValue(kind)), "wechat")
            assertEquals(text, document.rows.single().payload?.get("金额(元)"), kind)
        }
    }
    @Test fun numericAndExplicitlyEmptyErrorValuesRejectTheFile() {
        for (kind in listOf("empty", "number")) {
            assertEquals("statement_unreadable", assertFailsWith<StatementDocumentFailure>(kind) {
                readLocalCashXlsxDocument(Base64.decode(files.getValue(kind)), "wechat")
            }.code)
        }
    }
}
